--  mano ni clases que ya tenían texto largo aprobado.
-- ============================================================

DO $curso$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Registro Sanitario de Suplementos Dietarios$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Registro Sanitario de Suplementos Dietarios$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: suplementos dietarios en Colombia
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción al curso: suplementos dietarios en Colombia$t$
     AND m.title = $u$Unidad 1. Fundamentos: qué es un suplemento dietario y su marco normativo$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción al curso: suplementos dietarios en Colombia$t$, $u$Unidad 1. Fundamentos: qué es un suplemento dietario y su marco normativo$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Introducción al curso: suplementos dietarios en Colombia","texto":"En un titular de registros sanitarios que opera en Colombia, el titular cambia de fabricante y no sabe si eso exige modificar la autorización. Lo que está en juego es el criterio de introducción al curso: suplementos dietarios en Colombia. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar introducción al curso: suplementos dietarios en Colombia con tus propias palabras y reconocer por qué importa en curso de Registro Sanitario de Suplementos Dietarios.","Relacionar introducción al curso: suplementos dietarios en Colombia con unidad 1. Fundamentos: qué es un suplemento dietario y su marco normativo y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar introducción al curso: suplementos dietarios en Colombia y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Recorre el alcance del curso, el mercado de suplementos y por qué el QF regulatorio es clave frente al auge de productos fraudulentos."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, introducción al curso: suplementos dietarios en Colombia aparece en medio de una decisión que no admite improvisación: el titular cambia de fabricante y no sabe si eso exige modificar la autorización. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos: qué es un suplemento dietario y su marco normativo. El objetivo del curso es claro: Capacitar al Químico Farmacéutico para clasificar, formular, registrar, rotular, publicitar e importar suplementos dietarios conforme al Decreto 3249 de 2006 y sus modificaciones (Decretos 3863 de 2008 y 272 de 2009, Resolución 3096 de 2007), y para prevenir riesgos frente a productos fraudulentos y cambios normativos en curso. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Recorre el alcance del curso, el mercado de suplementos y por qué el QF regulatorio es clave frente al auge de productos fraudulentos.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 1. Fundamentos: qué es un suplemento dietario y su marco normativo y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Tabla de clasificación con vía y riesgos.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar introducción al curso: suplementos dietarios en Colombia, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Revisa los artículos 2, 3, 12, 24 y 25 del Decreto 3249. Evidencia que debe quedar: Registro del paso.","Clasifica cada producto. Evidencia que debe quedar: Registro del paso.","Indica la vía de trámite. Evidencia que debe quedar: Registro del paso.","Identifica qué declaraciones no se permiten. Evidencia que debe quedar: Registro del paso.","Indica qué productos requieren concepto de la Sala. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: Una empresa ficticia quiere lanzar (datos simulados): una bebida con proteína y vitaminas, cápsulas de melatonina, un polvo de colágeno con vitamina C y cápsulas de un extracto «para la próstata». Pregunta qué registro necesita cada uno. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar introducción al curso: suplementos dietarios en Colombia en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Introducción al curso: suplementos dietarios en Colombia»?","respuesta":"Recorre el alcance del curso, el mercado de suplementos y por qué el QF regulatorio es clave frente al auge de productos fraudulentos."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Tabla de clasificación con vía y riesgos.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Introducción al curso: suplementos dietarios en Colombia se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos: qué es un suplemento dietario y su marco normativo.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Mitos y verdades sobre los suplementos dietarios","url":"https://www.youtube.com/watch?v=fqeR_OYLYjA"},{"cita":"[Página web] Decreto 3249 de 2006: Regulación de suplementos dietarios en Colombia. INVIMA – Biblioteca (ES)","url":"https://www.invima.gov.co/biblioteca/decreto-3249-2006-suplementos-dietarios"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente introducción al curso: suplementos dietarios en Colombia en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de introducción al curso: suplementos dietarios en Colombia"}],"keywords":["curso","registro","sanitario","suplementos","dietarios","introducción","colombia","unidad","fundamentos","suplemento","dietario","marco"],"mapa":{"centro":"Introducción al curso: suplementos dietarios en Colombia","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios — productos especiales","Unidad 1. Fundamentos: qué es un suplemento dietario y su marco normativo","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Clasificación de un portafolio de cinco productos","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Revisa los artículos 2, 3, 12, 24 y 25 del Decreto 3249.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Clasifica cada producto.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Indica la vía de trámite.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Identifica qué declaraciones no se permiten.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Indica qué productos requieren concepto de la Sala.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Clasificación de un portafolio de cinco productos","contexto":"NutriAndes (ficticia) tiene cinco proyectos (datos simulados): (1) tabletas de vitamina D3 de 1.000 UI; (2) gomitas de vitamina C para niños; (3) cápsulas con un extracto vegetal y la frase «baja el azúcar»; (4) un polvo de proteína de suero como reemplazo de comidas; (5) un producto con un ingrediente botánico que no está en ninguna lista de referencia.","pregunta":"¿Qué decisión demuestra que entendiste introducción al curso: suplementos dietarios en Colombia?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 02. Definición legal de suplemento dietario
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Definición legal de suplemento dietario$t$
     AND m.title = $u$Unidad 1. Fundamentos: qué es un suplemento dietario y su marco normativo$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Definición legal de suplemento dietario$t$, $u$Unidad 1. Fundamentos: qué es un suplemento dietario y su marco normativo$u$;
  ELSE
