  -- 28. Casos recientes: 'potenciadores', 'detox', productos deportivos e infantiles
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Casos recientes: 'potenciadores', 'detox', productos deportivos e infantiles$t$
     AND m.title = $u$Unidad 5. Vigilancia, productos fraudulentos y comparación internacional$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
