     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 02. Ley 1787 de 2016: acceso seguro e informado al uso médico y científico
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Ley 1787 de 2016: acceso seguro e informado al uso médico y científico$t$
     AND m.title = $u$Unidad 1. Marco legal y gobernanza del cannabis medicinal en Colombia$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Ley 1787 de 2016: acceso seguro e informado al uso médico y científico$t$, $u$Unidad 1. Marco legal y gobernanza del cannabis medicinal en Colombia$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Ley 1787 de 2016: acceso seguro e informado al uso médico y científico","texto":"En un titular de registros sanitarios que opera en Colombia, un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. Lo que está en juego es el criterio de ley 1787 de 2016: acceso seguro e informado al uso médico y científico. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar ley 1787 de 2016: acceso seguro e informado al uso médico y científico con tus propias palabras y reconocer por qué importa en curso de Regulación Sanitaria del Cannabis Medicinal en Colombia.","Relacionar ley 1787 de 2016: acceso seguro e informado al uso médico y científico con unidad 1. Marco legal y gobernanza del cannabis medicinal en Colombia y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar ley 1787 de 2016: acceso seguro e informado al uso médico y científico y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Describe el objeto de la ley, el control estatal de la cadena, las competencias de MinSalud y MinJusticia y la protección de pequeños cultivadores."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, ley 1787 de 2016: acceso seguro e informado al uso médico y científico aparece en medio de una decisión que no admite improvisación: un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Marco legal y gobernanza del cannabis medicinal en Colombia. El objetivo del curso es claro: Que el Químico Farmacéutico identifique la autoridad, la licencia, el cupo y la vía sanitaria que corresponden a cada material y producto de cannabis, y planifique y ejecute los trámites ante INVIMA, MinJusticia y el FNE cumpliendo la normativa vigente a 2026. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Describe el objeto de la ley, el control estatal de la cadena, las competencias de MinSalud y MinJusticia y la protección de pequeños cultivadores.","Una pregunta que se usa para comprobar esta clase es: «¿Cuál es el objeto de la Ley 1787 de 2016?» La respuesta correcta se apoya en lo siguiente: La Ley 1787 de 2016 crea un marco regulatorio para el acceso seguro e informado al uso médico y científico del cannabis y sus derivados, con control del Estado sobre la cadena (semillas, cultivo, fabricación, comercialización). La fuente citada es: Ley 1787 de 2016.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Marco legal y gobernanza del cannabis medicinal en Colombia y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Tabla de actividades con licencias, cupos y autoridades.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar ley 1787 de 2016: acceso seguro e informado al uso médico y científico, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Clasifica cada material como psicoactivo o no psicoactivo. Evidencia que debe quedar: Registro del paso.","Identifica la licencia y la autoridad de cada actividad. Evidencia que debe quedar: Registro del paso.","Indica si la actividad requiere cupo. Evidencia que debe quedar: Registro del paso.","Indica el papel del FNE. Evidencia que debe quedar: Registro del paso.","Indica qué autorización sanitaria requeriría cada producto terminado. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar ley 1787 de 2016: acceso seguro e informado al uso médico y científico en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Ley 1787 de 2016: acceso seguro e informado al uso médico y científico»?","respuesta":"Describe el objeto de la ley, el control estatal de la cadena, las competencias de MinSalud y MinJusticia y la protección de pequeños cultivadores."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Tabla de actividades con licencias, cupos y autoridades.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Ley 1787 de 2016: acceso seguro e informado al uso médico y científico se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Marco legal y gobernanza del cannabis medicinal en Colombia.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Ley 1787 de 2016 — marco regulatorio del acceso seguro e informado al uso médico y científico del cannabis (copia INVIMA). INVIMA (ES)","url":"https://www.invima.gov.co/biblioteca/preview/127387"},{"cita":"[Página web] Marco normativo: cannabis para uso médico y científico (documento INVIMA, contexto 2016–2018). INVIMA (ES)","url":"https://www.invima.gov.co/biblioteca/preview/122395"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente ley 1787 de 2016: acceso seguro e informado al uso médico y científico en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de ley 1787 de 2016: acceso seguro e informado al uso médico y científico"}],"keywords":["curso","regulación","sanitaria","cannabis","medicinal","colombia","acceso","seguro","informado","médico","científico","unidad"],"mapa":{"centro":"Ley 1787 de 2016: acceso seguro e informado al uso médico y científico","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios — productos especiales","Unidad 1. Marco legal y gobernanza del cannabis medicinal en Colombia","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Clasificación de materiales y actividades con cannabis","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Clasifica cada material como psicoactivo o no psicoactivo.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Identifica la licencia y la autoridad de cada actividad.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Indica si la actividad requiere cupo.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Indica el papel del FNE.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Indica qué autorización sanitaria requeriría cada producto terminado.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Ley 1787 de 2016: acceso seguro e informado al uso médico y científico","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 1. Marco legal y gobernanza del cannabis medicinal en Colombia: CannaAndes (ficticia) planea (datos simulados): (1) cultivar plantas con THC del 0,4 % para obtener CBD; (2) cultivar plantas con THC del 12 % para investigación médica; (3) fabricar un aceite de CBD con trazas de THC; (4) fabricar un extracto con THC alto para un medicamento; (5) vender grano para alimentos. La pregunta que decide esta clase es: ¿Cuál es el objeto de la Ley 1787 de 2016?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Legalizar el consumo recreativo de cannabis en todo el territorio nacional sin restricciones.","correcta":false,"retro":"La ley no regula el uso recreativo."},{"texto":"Crear un marco regulatorio para el acceso seguro e informado al uso médico y científico del cannabis.","correcta":true,"retro":"Correcto. Con control estatal de la cadena."},{"texto":"Prohibir toda actividad relacionada con el cannabis, incluida la investigación científica.","correcta":false,"retro":"La ley habilita usos médicos y científicos."},{"texto":"Autorizar la venta libre de flor de cannabis en tiendas naturistas del país.","correcta":false,"retro":"No es el objeto de la ley."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
