  -- 11. Licencias de cultivo: modalidad de uso nacional y exportación, investigación no comercial y pequeños cultivadores
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
