     AND l.title = $t$Licencias de cultivo: modalidad de uso nacional y exportación, investigación no comercial y pequeños cultivadores$t$
     AND m.title = $u$Unidad 2. Licencias y cupos$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
