  -- 14. Caso: solicitud de un cupo ordinario de fabricación
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso: solicitud de un cupo ordinario de fabricación$t$
     AND m.title = $u$Unidad 2. Licencias y cupos$u$
   ORDER BY l.id LIMIT 1;
