  -- 32. Estados Unidos: reclasificación parcial a Lista III (2025–2026) y otros mercados
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Estados Unidos: reclasificación parcial a Lista III (2025–2026) y otros mercados$t$
     AND m.title = $u$Unidad 5. Tendencias internacionales y casos integradores$u$
   ORDER BY l.id LIMIT 1;
