  -- 14. Caso: solicitud de certificación BPER de una radiofarmacia hospitalaria
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso: solicitud de certificación BPER de una radiofarmacia hospitalaria$t$
     AND m.title = $u$Unidad 2. Marco sanitario colombiano: BPER, certificación y registro$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso: solicitud de certificación BPER de una radiofarmacia hospitalaria$t$, $u$Unidad 2. Marco sanitario colombiano: BPER, certificación y registro$u$;
