  -- 31. Farmacovigilancia y tecnovigilancia en la cadena de gases
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Farmacovigilancia y tecnovigilancia en la cadena de gases$t$
     AND m.title = $u$Unidad 5. Pandemia, vigilancia y casos integradores$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Farmacovigilancia y tecnovigilancia en la cadena de gases$t$, $u$Unidad 5. Pandemia, vigilancia y casos integradores$u$;
