    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases completas con experiencia interactiva (catálogo).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;
  RAISE NOTICE 'Experiencias de %: % clases.', $t$Curso de Regulación Sanitaria de Gases Medicinales$t$, v_n;
END $curso$;

-- ============================================================
--  Experiencias de clase: Curso de Importación de Medicamentos Vitales No Disponibles
--
--  Generado por scripts/generar-experiencias-catalogo.mjs a partir del
--  resumen de cada clase, los enlaces verificados y el material de
--  evaluación de contenido/aula/catalogo. No editar a mano.
--
--  33 clases. No toca cursos con experiencia escrita a
--  mano ni clases que ya tenían texto largo aprobado.
-- ============================================================

DO $curso$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Importación de Medicamentos Vitales No Disponibles$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Importación de Medicamentos Vitales No Disponibles$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia$t$
     AND m.title = $u$Unidad 1. Fundamentos del régimen de Medicamentos Vitales No Disponibles$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia$t$, $u$Unidad 1. Fundamentos del régimen de Medicamentos Vitales No Disponibles$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia","texto":"En un titular de registros sanitarios que opera en Colombia, un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. Lo que está en juego es el criterio de introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia con tus propias palabras y reconocer por qué importa en curso de Importación de Medicamentos Vitales No Disponibles.","Relacionar introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia con unidad 1. Fundamentos del régimen de Medicamentos Vitales No Disponibles y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Presenta el propósito del régimen MVND, los actores (INVIMA, MinSalud, EPS, IPS, importadores, FNE) y la ruta del curso."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia aparece en medio de una decisión que no admite improvisación: un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos del régimen de Medicamentos Vitales No Disponibles. El objetivo del curso es claro: Que el Químico Farmacéutico determine cuándo procede la vía MVND, prepare y radique correctamente las solicitudes de autorización en sus distintas modalidades, gestione el visto bueno de importación en VUCE y asuma las responsabilidades de calidad, trazabilidad y farmacovigilancia del importador. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Presenta el propósito del régimen MVND, los actores (INVIMA, MinSalud, EPS, IPS, importadores, FNE) y la ruta del curso.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 1. Fundamentos del régimen de Medicamentos Vitales No Disponibles y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Matriz de decisión con alternativas.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Construye una matriz con los criterios de los artículos 2 y 4. Evidencia que debe quedar: Registro del paso.","Aplica la matriz a cada caso. Evidencia que debe quedar: Registro del paso.","Decide si procede la vía y con qué modalidad. Evidencia que debe quedar: Registro del paso.","Propón alternativas para los casos en que no procede. Evidencia que debe quedar: Registro del paso.","Indica qué evidencia documental soportaría cada decisión. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia»?","respuesta":"Presenta el propósito del régimen MVND, los actores (INVIMA, MinSalud, EPS, IPS, importadores, FNE) y la ruta del curso."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Matriz de decisión con alternativas.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos del régimen de Medicamentos Vitales No Disponibles.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"[Página web] Medicamentos Vitales No Disponibles (normatividad, listados, formatos, requisitos y preguntas frecuentes). INVIMA (ES)","url":"https://www.invima.gov.co/productos-vigilados/medicamentos-y-productos-biologicos/medicamentos-vitales-no-disponibles"},{"cita":"[Página web] Medicamentos Vitales No Disponibles – Invima con sección exclusiva. ConsultorSalud (ES)","url":"https://consultorsalud.com/medicamentos-vitales-no-disponibles-invima-con-seccion-exclusiva"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia"}],"keywords":["curso","importación","medicamentos","vitales","disponibles","introducción","acceso","registro","sanitario","colombia","unidad","fundamentos"],"mapa":{"centro":"Introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios — productos especiales","Unidad 1. Fundamentos del régimen de Medicamentos Vitales No Disponibles","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: ¿Procede la vía de vital no disponible? Tres escenarios","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Construye una matriz con los criterios de los artículos 2 y 4.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Aplica la matriz a cada caso.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Decide si procede la vía y con qué modalidad.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Propón alternativas para los casos en que no procede.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Indica qué evidencia documental soportaría cada decisión.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"¿Procede la vía de vital no disponible? Tres escenarios","contexto":"El comité de farmacia del Hospital Pediátrico del Norte (ficticio) analiza tres casos (datos simulados): (1) un antídoto para una intoxicación rara cuyo único titular dejó de comercializarlo en Colombia; (2) un antiepiléptico con registro, disponible en el país, que una familia quiere importar porque es más barato en otro país; (3) un medicamento para una enfermedad rara que solo está en ensayo clínico de fase II.","pregunta":"¿Qué decisión demuestra que entendiste introducción al curso: el acceso a medicamentos sin registro sanitario en Colombia?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 02. Decreto 481 de 2004: estructura y artículos clave
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Decreto 481 de 2004: estructura y artículos clave$t$
     AND m.title = $u$Unidad 1. Fundamentos del régimen de Medicamentos Vitales No Disponibles$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
