  -- 27. Caso práctico: opioide desabastecido para una red hospitalaria
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso práctico: opioide desabastecido para una red hospitalaria$t$
     AND m.title = $u$Unidad 4. Desabastecimiento, enfermedades huérfanas y medicamentos de control especial$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso práctico: opioide desabastecido para una red hospitalaria$t$, $u$Unidad 4. Desabastecimiento, enfermedades huérfanas y medicamentos de control especial$u$;
